#include "Demosaic.h"
#include "CameraProfileEngine.h"
#include <QCoreApplication>
#include <QFile>
#include <QJsonDocument>
#include <QJsonObject>
#include <QJsonArray>
#include <opencv2/core.hpp>
#include <algorithm>
#include <cmath>
#include <iostream>
#include <memory>
#include <random>
#include <stdexcept>
#include <vector>

namespace {
void require(bool ok,const char *message) {if(!ok)throw std::runtime_error(message);}

class Moments {
public:
    void add(const cv::Mat &rgb)
    {
        require(rgb.type()==CV_32FC3&&rgb.total()>1&&cv::checkRange(rgb),"Invalid RGB sample");
        cv::Mat centered=rgb-cv::mean(rgb),samples;
        centered.reshape(1,int(rgb.total())).convertTo(samples,CV_64F);
        if(m_count==0) {m_sum=cv::Mat::zeros(samples.size(),CV_64F);m_cross=cv::Mat::zeros(3,3,CV_64F);}
        require(samples.size()==m_sum.size(),"Changed sample geometry");
        m_sum+=samples;m_cross+=samples.t()*samples;++m_count;
    }
    cv::Mat covariance() const
    {
        require(m_count>1,"Need repeated samples");
        cv::Mat cross=m_cross-(m_sum.t()*m_sum)/double(m_count);
        return cross/(double(m_count-1)*double(m_sum.rows-1));
    }
private:
    int m_count=0;
    cv::Mat m_sum,m_cross;
};

QJsonArray matrix(const cv::Mat &value)
{
    QJsonArray rows;for(int y=0;y<3;++y){QJsonArray row;for(int x=0;x<3;++x)row.append(value.at<double>(y,x));rows.append(row);}return rows;
}

void selfTest()
{
    Moments moments;
    cv::Mat a(4,4,CV_32FC3),b(4,4,CV_32FC3);
    for(int y=0;y<4;++y)for(int x=0;x<4;++x){const float v=float(y*4+x);a.at<cv::Vec3f>(y,x)={v,2*v,3*v};b.at<cv::Vec3f>(y,x)={-v,-2*v,-3*v};}
    moments.add(a);moments.add(b);const auto c=moments.covariance();
    require(std::abs(c.at<double>(0,0)-2.*(16.*17./12.))<1e-9,"Covariance denominator wrong");
    require(std::abs(c.at<double>(0,1)-2*c.at<double>(0,0))<1e-9,"Lost covariance");
}
}

int main(int argc,char **argv)
{
    QCoreApplication app(argc,argv);
    try {
        if(argc==2&&app.arguments()[1]=="--self-test"){selfTest();std::cout<<"PASS\n";return 0;}
        require(argc==3,"Usage: iprLocalNoiseTransport request-json output-json");
        QFile input(app.arguments()[1]);require(input.open(QIODevice::ReadOnly)&&input.size()<1024*1024,"Invalid request file");
        QJsonParseError parse;const auto document=QJsonDocument::fromJson(input.readAll(),&parse);
        require(parse.error==QJsonParseError::NoError&&document.isObject(),"Invalid request JSON");
        const auto request=document.object();const int trials=request["trials"].toInt();
        require(trials>=16&&trials<=64&&trials%2==0,"Trials must be even,16..64");
        const auto cases=request["cases"].toArray();require(!cases.isEmpty()&&cases.size()<=96,"Invalid case count");
        cv::setNumThreads(2);QJsonArray records;
        QFile fields(request["mean_fields"].toString());
        const bool control=request.contains("mean_fields");
        if(control)require(fields.open(QIODevice::ReadOnly),"Cannot open mean fields");
        QFile rawFields(request["raw_mean_fields"].toString());
        const bool spatialRaw=request.contains("raw_mean_fields");
        if(spatialRaw)require(rawFields.open(QIODevice::ReadOnly),"Cannot open RAW fields");
        require(!(control&&spatialRaw),"RAW and camera interventions must be separate");
        const Demosaic::Pattern pattern{{{0,1},{1,2}}};
        constexpr int side=512;const cv::Rect core(192,192,128,128);
        for(const auto &item:cases) {
            const auto c=item.toObject();const auto means=c["mean_raw_dn"].toArray(),variances=c["raw_variance_dn2"].toArray();
            const auto blacks=c["applied_black_dn"].toArray(),multipliers=c["pre_mul"].toArray();
            require(means.size()==4&&variances.size()==4&&blacks.size()==4&&multipliers.size()==4,"Need four CFA phases/channels");
            const double maximum=c["maximum"].toDouble();require(maximum>0&&std::isfinite(maximum),"Invalid effective maximum");
            for(int k=0;k<4;++k)require(std::isfinite(means[k].toDouble())&&variances[k].toDouble()>0&&std::isfinite(variances[k].toDouble())&&multipliers[k].toDouble()>0,"Invalid noise law inputs");
            cv::Mat rawMean;
            const bool useRawField=spatialRaw&&c.contains("raw_field_offset");
            const auto slopes=c["slopes"].toArray(),reference=c["reference_black_dn"].toArray(),dark=c["dark_variance_dn2"].toArray();
            if(useRawField){
                rawMean.create(side,side,CV_32F);
                const qint64 bytes=qint64(rawMean.total()*rawMean.elemSize()),offset=qint64(c["raw_field_offset"].toDouble(-1));
                require(offset>=0&&offset+bytes<=rawFields.size()&&rawFields.seek(offset),"Invalid RAW field offset");
                require(rawFields.read(reinterpret_cast<char *>(rawMean.data),bytes)==bytes&&cv::checkRange(rawMean),"Invalid RAW mean field");
                require(slopes.size()==4&&reference.size()==4&&dark.size()==4,"Missing spatial noise law");
                for(int k=0;k<4;++k)require(slopes[k].toDouble(-1)>=0&&dark[k].toDouble(-1)>0&&reference[k].isDouble(),"Invalid spatial noise parameters");
            }
            CameraProfileEngine::DcpRenderOptions options;
            options.cameraBaselineExposureEv=c["baseline_exposure_ev"].toDouble();
            options.profileExposureCompensationEv=c["profile_exposure_compensation_ev"].toDouble();
            options.preserveToneCurveHue=c["preserve_tone_curve_hue"].toBool();
            const QString profile=c["profile"].toString();require(QFile::exists(profile),"Profile missing");
            const double kelvin=c["source_kelvin"].toDouble();require(kelvin>=2000&&kelvin<=50000,"Invalid source Kelvin");
            std::mt19937_64 rng(quint64(c["seed"].toDouble()));std::normal_distribution<double> gaussian;
            Moments camera,working,cameraA,cameraB,workingA,workingB;
            std::vector<cv::Mat> samples;
            std::array<std::uint64_t,4> zeros{};
            for(int trial=0;trial<trials;++trial) {
                auto pixels=std::make_unique<Demosaic::Pixel[]>(side*side);
                for(int y=0;y<side;++y)for(int x=0;x<side;++x) {
                    const int phase=2*(y&1)+(x&1),channel=phase==2?3:phase==3?2:phase;
                    const double mean=useRawField?double(rawMean.at<float>(y,x)):means[phase].toDouble();
                    const double variance=useRawField?dark[phase].toDouble()+slopes[phase].toDouble()*std::max(mean-reference[phase].toDouble(),0.):variances[phase].toDouble();
                    const double sample=mean+std::sqrt(variance)*gaussian(rng);
                    const int raw=std::clamp(int(std::lround(sample)),0,16383);
                    const int shifted=std::max(0,raw-blacks[channel].toInt());
                    const int scaled=std::clamp(int(shifted*multipliers[channel].toDouble()*65535./maximum),0,65535);
                    if(scaled==0)++zeros[size_t(phase)];
                    pixels[size_t(y)*side+x][pattern[size_t(y&1)][size_t(x&1)]]=std::uint16_t(scaled);
                }
                require(Demosaic::interpolate(pixels.get(),side,side,pattern,Demosaic::OpeningMedian,{}),"Simulation demosaic failed");
                cv::Mat rgb(core.height,core.width,CV_32FC3);
                for(int y=0;y<core.height;++y)for(int x=0;x<core.width;++x){const auto &p=pixels[size_t(y+core.y)*side+x+core.x];rgb.at<cv::Vec3f>(y,x)={p[0]/65535.f,p[1]/65535.f,p[2]/65535.f};}
                camera.add(rgb);(trial<trials/2?cameraA:cameraB).add(rgb);
                if(control)samples.push_back(rgb.clone());
                QString error;require(CameraProfileEngine::applyDcp(profile,rgb,kelvin,&error,options),"Simulation profile failed");
                working.add(rgb);(trial<trials/2?workingA:workingB).add(rgb);
            }
            QJsonArray zeroFractions;for(auto n:zeros)zeroFractions.append(double(n)/(double(trials)*side*side/4.));
            QJsonObject result{{"case_id",c["case_id"]},{"covariance_camera",matrix(camera.covariance())},
                {"covariance_working",matrix(working.covariance())},{"first_half_camera",matrix(cameraA.covariance())},
                {"second_half_camera",matrix(cameraB.covariance())},{"first_half_working",matrix(workingA.covariance())},
                {"second_half_working",matrix(workingB.covariance())},{"pre_rcd_zero_fractions",zeroFractions}};
            if(control){
                cv::Mat meanField(128,128,CV_32FC3);
                const qint64 bytes=qint64(meanField.total()*meanField.elemSize());
                const qint64 offset=qint64(c["mean_field_offset"].toDouble(-1));
                require(offset>=0&&offset+bytes<=fields.size()&&fields.seek(offset),"Invalid field offset");
                require(fields.read(reinterpret_cast<char *>(meanField.data),bytes)==bytes&&cv::checkRange(meanField),"Invalid mean field");
                cv::Mat ensemble=cv::Mat::zeros(meanField.size(),CV_32FC3);
                for(const auto &sample:samples)ensemble+=sample;
                ensemble/=float(trials);
                const auto uniform=cv::mean(meanField);
                Moments fieldOutput,uniformOutput,noiseInput;
                double minField=1.,minUniform=1.;
                for(const auto &sample:samples){
                    cv::Mat residual=sample-ensemble;
                    noiseInput.add(residual);
                    cv::Mat spatial=meanField+residual,flat=residual+uniform;
                    double low=0.;cv::minMaxLoc(spatial.reshape(1),&low);minField=std::min(minField,low);
                    cv::minMaxLoc(flat.reshape(1),&low);minUniform=std::min(minUniform,low);
                    QString error;
                    require(CameraProfileEngine::applyDcp(profile,spatial,kelvin,&error,options),"Spatial control DCP failed");
                    require(CameraProfileEngine::applyDcp(profile,flat,kelvin,&error,options),"Uniform control DCP failed");
                    fieldOutput.add(spatial);uniformOutput.add(flat);
                }
                result["controlled_field_covariance"]=matrix(fieldOutput.covariance());
                result["controlled_uniform_covariance"]=matrix(uniformOutput.covariance());
                result["centered_input_covariance"]=matrix(noiseInput.covariance());
                result["min_spatial_input"]=minField;result["min_uniform_input"]=minUniform;
            }
            records.append(result);
            std::cout<<"CASE "<<c["case_id"].toString().toStdString()<<" completed\n"<<std::flush;
        }
        QFile output(app.arguments()[2]);require(output.open(QIODevice::WriteOnly|QIODevice::NewOnly),"Output exists");
        const auto bytes=QJsonDocument(QJsonObject{{"trials",trials},{"tile",side},{"core",QJsonArray{core.x,core.y,core.width,core.height}},{"records",records}}).toJson();
        require(output.write(bytes)==bytes.size(),"Incomplete output");return 0;
    } catch(const std::exception &e) {std::cerr<<e.what()<<'\n';return 1;}
}
